class InputMetadataEvaluationTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String INPUT = "callerInput";
	private static final String OUTPUT = "visible";

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void originalNameMembershipSelectsTheActualLateralProjectionScope(boolean experimental) {
		TupleExpr right = hiddenInputProjection();
		TupleExpr withOriginal = LateralQueryEvaluationStep.prepareRightScope(right, Set.of(INPUT), Set.of(INPUT));
		TupleExpr withoutOriginal = LateralQueryEvaluationStep.prepareRightScope(right, Set.of(INPUT), Set.of());
		assertThat(withOriginal).isSameAs(right);
		assertThat(withoutOriginal).isNotSameAs(right);
		Filter hiddenGuard = (Filter) ((Projection) ((Join) withoutOriginal).getLeftArg()).getArg();
		assertThat(((Var) ((Bound) hiddenGuard.getCondition()).getArg()).getName())
				.startsWith("-lateral-hidden-")
				.endsWith("-" + INPUT);

		Lateral lateral = new Lateral(values(), right, Set.of(INPUT));
		// A new LATERAL name cannot leak through a nested SELECT that does not project it.
		assertThat(rows(lateral.clone(), EmptyBindingSet.getInstance(), experimental)).isEmpty();
		// A genuine original query parameter is in the original domain, so that renaming is inapplicable.
		BindingSet request = BindingSetOrigin.requestInput(input());
		List<BindingSet> actual = rows(lateral.clone(), request, experimental);
		assertThat(actual).hasSize(1);
		assertThat(actual.getFirst().getValue(INPUT)).isEqualTo(VF.createLiteral(1));
		assertThat(actual.getFirst().getValue(OUTPUT)).isEqualTo(VF.createLiteral(2));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void requiredFilterInputUsesCorrelatedJoinWithoutInventingAnOutput(boolean experimental) {
		Filter dependent = constantFilter(true);
		assertThat(dependent.getBindingNames()).isEmpty();
		Join join = new Join(values(), dependent);
		List<BindingSet> actual = rows(join, EmptyBindingSet.getInstance(), experimental);
		assertThat(join.getAlgorithmName()).isEqualTo(JoinIterator.class.getSimpleName());
		assertThat(actual).hasSize(1);
		assertThat(actual.getFirst().getBindingNames()).containsExactly(INPUT);
		assertThat(actual.getFirst().getValue(INPUT)).isEqualTo(VF.createLiteral(1));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void requiredFilterInputCannotCrossAnIndependentProjection(boolean experimental) {
		Projection closed = new Projection(constantFilter(true), new ProjectionElemList(), true);
		Join invalid = new Join(values(), closed);
		assertThatThrownBy(() -> strategy(experimental).precompile(invalid, new QueryEvaluationContext.Minimal(null)))
				.isInstanceOf(QueryEvaluationException.class)
				.hasMessage("Required FILTER parameters cannot cross an independent scope");
		Projection independent = new Projection(constantFilter(false), new ProjectionElemList(), true);
		List<BindingSet> actual = rows(new Join(values(), independent), EmptyBindingSet.getInstance(), experimental);
		assertThat(actual).hasSize(1);
		assertThat(actual.getFirst().getValue(INPUT)).isEqualTo(VF.createLiteral(1));
	}

	private static TupleExpr hiddenInputProjection() {
		Extension local = new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(VF.createLiteral(2)), OUTPUT));
		Filter guard = new Filter(local, new Bound(Var.of(INPUT)));
		guard.setConditionBindingScope(ConditionBindingScope.ALL);
		Projection projection = new Projection(guard, new ProjectionElemList(new ProjectionElem(OUTPUT)), true);
		// The unit is nested, rather than the direct-SELECT LATERAL exemption.
		return new Join(projection, new SingletonSet());
	}

	private static Filter constantFilter(boolean required) {
		Filter filter = new Filter(new SingletonSet(), new ValueConstant(VF.createLiteral(true)));
		filter.setConditionBindingScope(ConditionBindingScope.ALL);
		if (required) {
			filter.setRequiredInputBindingNames(Set.of(INPUT));
		}
		return filter;
	}

	private static BindingSetAssignment values() {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(List.of(input()));
		return values;
	}

	private static QueryBindingSet input() {
		QueryBindingSet bindings = new QueryBindingSet();
		bindings.addBinding(INPUT, VF.createLiteral(1));
		return bindings;
	}

	private static DefaultEvaluationStrategy strategy(boolean experimental) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.of(experimental));
		return strategy;
	}

	private static List<BindingSet> rows(TupleExpr expression, BindingSet input, boolean experimental) {
		List<BindingSet> result = new ArrayList<>();
		try (var rows = strategy(experimental).precompile(expression, new QueryEvaluationContext.Minimal(null))
				.evaluate(input)) {
			while (rows.hasNext()) {
				result.add(new QueryBindingSet(rows.next()));
			}
		}
		return result;
	}
}
